function NoetherCharge(dL_dv, xi, q, v):
    p <- dL_dv(q, v)      // conjugate momentum, O(n)
    eta <- xi(q)           // symmetry generator, O(n)
    return dot(p, eta)     // inner product, O(n)

Complexity: O(n) time, O(n) space
